/* ═══════════════════════════════════════════════════════════════════════════
   PREMIUM · MARKETING 360° — Tokens de identidade visual
   Fonte da verdade dos tokens da Agência Premium. Consumido por todos os
   sistemas (Tasks, Central de Mídia, Ultra Popular, portais).
   Arquitetura em camadas:
     1A. Marca crua (--brand-*)  — fixa nos dois temas
     1B. Semântica (--c-*)       — ÚNICA camada que muda por tema (html.dark)
   A escala neutra literal (--premium-*) é fachada de compatibilidade: no claro
   mantém os valores originais; no escuro é recalibrada (texto vence).
   ═══════════════════════════════════════════════════════════════════════════ */

:root {
  /* ── Camada 1A · Marca crua (fixa nos dois temas) ──────────────────────────
     Cores literais da marca. Nunca mudam entre claro/escuro. */
  --brand-yellow: #FBDA25;
  --brand-gold: #FCD028;
  --brand-amber: #F7BA30;
  --brand-ink: #0A0A0A;    /* âncora escura da marca: sidebar, btn-dark, banners */
  --brand-on-ink: #FFFFFF; /* texto sobre a âncora escura */

  /* Aliases de marca mantidos para compatibilidade com componentes existentes. */
  --yellow: var(--brand-yellow);
  --gold: var(--brand-gold);
  --amber: var(--brand-amber);
  --yellow-50: #FFFBE0;    /* SOMENTE anel de foco (0 0 0 2px); nunca fundo — use --gold-bg */

  /* Par temático de fundo amarelo suave (seleção, callouts, destaques). No claro
     vale o valor histórico de --yellow-50; html.dark dá um tom escuro dourado
     próprio (nunca o claro com opacidade). */
  --gold-bg: #FFFBE0;

  /* Amarelo de alerta sobre chip escuro (par invertido, ex.: cronômetro parado).
     No claro o chip é escuro → amarelo da marca (AA). No escuro o chip fica
     claro; o valor é escurecido em html.dark para manter AA de texto pequeno
     ("amarelo só em fundo escuro"). Só cor por token — componente nunca usa hex. */
  --timer-idle: var(--brand-yellow);

  /* Escala neutra literal — valores do modo CLARO (inalterados). */
  --premium-black: #000000;
  --premium-ink: #0A0A0A;
  --premium-coal: #1A1A1A;
  --premium-graphite: #2A2A2A;
  --premium-steel: #4A4A4A;
  --premium-gray: #6B6B6B; /* AA de texto (5,33:1 sobre branco, ~4,8:1 sobre bone); v0.25.0 */
  --premium-silver: #BFBFBF;
  --premium-mist: #E5E5E5;
  --premium-bone: #F2F2F2;
  --premium-paper: #FAFAFA;
  --premium-white: #FFFFFF;

  /* ── Camada 1B · Semântico --c-* (varia por tema) ──────────────────────────
     No claro aponta para os neutros claros. Trocar tema = sobrescrever estes. */
  --c-bg: var(--premium-paper);            /* fundo da página */
  --c-surface: var(--premium-white);       /* superfície de card */
  --c-sunken: var(--premium-bone);         /* chip, thead, tabs, segmented */
  --c-ink: var(--premium-ink);             /* texto principal */
  --c-muted: var(--premium-gray);          /* texto auxiliar */
  --c-subtle: var(--premium-silver);       /* ícones / desabilitado */
  --c-border: var(--premium-mist);         /* borda padrão */
  --c-border-strong: var(--premium-graphite); /* borda forte */

  /* Zona "sempre escura" da marca (sidebar): escura nos dois temas, só eleva
     levemente no escuro para separar da página. */
  --c-sidebar: var(--brand-ink);
  --c-sidebar-elevated: #1A1A1A;
  --c-sidebar-muted: #BFBFBF;
  --c-sidebar-section: #4A4A4A; /* rótulos de seção / cadeado (dim) */

  /* Ênfase neutra (btn-dark / chips e tabs invertidos): preto no claro,
     inverte para claro no escuro — um preto sobre página preta sumiria. */
  --c-emphasis: var(--brand-ink);
  --c-on-emphasis: var(--brand-on-ink);
  --c-emphasis-hover: #2A2A2A;

  --success: #1E8E4A;
  --success-bg: #E6F4EA;
  --warning: #C97A0F;
  --warning-bg: #FFF3DB;
  --danger: #C0322B;
  --danger-bg: #FBE9E7;
  --info: #1A6FB0;
  --info-bg: #E6F1FA;

  /* Alerta fixo (padrão "Alerta fixo", v0.8.0): vermelho SÓLIDO, igual nos dois
     temas, para aviso que fica na tela até a pessoa agir. Não é --danger: no
     escuro --danger vira #e87a72, um tom claro feito para TEXTO, que perde a
     urgência como fundo. Texto sobre ele é sempre --on-alert-solid (5,6:1).
     Não redefinir no bloco escuro. Como texto sobre superfície, use --danger. */
  --alert-solid: #C0322B;
  --alert-solid-hover: #A82A24;
  --on-alert-solid: #FFFFFF;

  --violet: #6E56CF;
  --violet-bg: #EDE9FB;
  --teal: #0E8C8C;
  --teal-bg: #E2F3F3;
  --slate: #5B6472;
  --slate-bg: #EDF0F3;

  --r-sm: 6px;
  --r-md: 8px;
  --r-lg: 12px;
  --r-xl: 18px;
  --r-pill: 999px;

  --sh-sm: 0 1px 3px rgba(10,10,10,.08), 0 1px 2px rgba(10,10,10,.04);
  --sh-md: 0 4px 12px rgba(10,10,10,.08), 0 2px 4px rgba(10,10,10,.04);
  --sh-lg: 0 12px 32px rgba(10,10,10,.12), 0 4px 8px rgba(10,10,10,.06);
  --sh-gold: 0 12px 28px rgba(251,218,37,.40), 0 4px 8px rgba(247,186,48,.22);

  --ease: cubic-bezier(.22,.61,.36,1);
  /* Curvas do painel de cards flutuantes (v0.10.0). A mola passa de 1 no eixo y:
     rebote curto só nas ENTRADAS do painel e no pulso do botão de lido. A saída
     acelera (ease-in) e é sempre mais curta que a entrada. Movimento, não cor:
     iguais nos dois temas, não redefinir no bloco escuro. Não usar fora desses
     padrões (a curva de todo o resto continua sendo --ease). */
  --ease-mola: cubic-bezier(.3,1.35,.5,1);
  --ease-sai: cubic-bezier(.4,0,1,1);

  /* ── Code theme (realce de sintaxe em documentação) ────────────────────────
     O realce é a exceção controlada à regra "sem hex em componente": as cores
     de sintaxe vivem como tokens aqui (camada de valor) e o componente nunca
     usa hex. Valores do tema CLARO; html.dark sobrescreve. Contraste AA. */
  --code-bg: #f6f6f4;
  --code-fg: #1a1a1a;
  --code-border: #e5e5e5;
  --code-keyword: #8a3ffc;     /* palavras-chave / métodos HTTP */
  --code-string: #0f7b46;     /* strings */
  --code-number: #9a5b00;     /* números / booleanos / null */
  --code-comment: #6a6a6a;    /* comentários */
  --code-property: #1565a8;   /* chaves de objeto / propriedades */
  --code-punct: #4a4a4a;      /* pontuação */
}

/* ── Tema escuro · sobrescreve a camada semântica + neutros + status ──────────
   Paleta calibrada à mão (ref. midia.agpremium.com.br), NÃO inversão. */
html.dark {
  /* Semântico --c-* */
  --c-bg: #0a0a0a;
  --c-surface: #161616;
  --c-sunken: #202020;
  --c-ink: #fafafa;
  --c-muted: #b8b8b8;
  --c-subtle: #8a8a8a;
  --c-border: #2e2e2e;
  --c-border-strong: #4a4a4a;

  /* Sidebar eleva-se acima da página (#0a0a0a) para criar separação. */
  --c-sidebar: #161616;
  --c-sidebar-elevated: #232323;
  --c-sidebar-section: #6a6a6a;
  /* --c-sidebar-muted permanece claro: a sidebar é sempre escura. */

  /* Ênfase inverte: botão claro sobre página escura tem alto contraste. */
  --c-emphasis: #fafafa;
  --c-on-emphasis: #0a0a0a;
  --c-emphasis-hover: #e2e2e2;

  /* Neutros --premium-* recalibrados (texto vence: ink/coal/graphite claros).
     Superfícies intencionalmente escuras usam --brand-ink (ver componentes). */
  --premium-paper: #0a0a0a;   /* → --c-bg */
  --premium-white: #161616;   /* → --c-surface */
  --premium-bone: #202020;    /* → --c-sunken */
  --premium-mist: #2e2e2e;    /* → --c-border */
  --premium-graphite: #4a4a4a;/* → --c-border-strong */
  --premium-silver: #5a5a5a;  /* ícones / desabilitado */
  --premium-gray: #b8b8b8;    /* → --c-muted */
  --premium-steel: #d0d0d0;   /* texto secundário */
  --premium-coal: #f2f2f2;    /* texto / hover claro */
  --premium-ink: #fafafa;     /* → --c-ink (texto principal) */
  /* --premium-black permanece #000 (reservado a banner de marca). */

  /* Status recalibrados para fundo escuro */
  --success: #34d17d;  --success-bg: #0f2e1d;
  --warning: #e6b24a;  --warning-bg: #2e2410;
  --danger: #e87a72;   --danger-bg: #2e1513;
  --info: #5aa6dd;     --info-bg: #102433;

  /* Tons auxiliares (fundos escuros próprios, sem opacidade) */
  --violet: #a594e8;   --violet-bg: #211a33;
  --teal: #4cc3c3;     --teal-bg: #0f2b2b;
  --slate: #9aa3b2;    --slate-bg: #1c212a;
  --gold-bg: #2e2410;  /* fundo amarelo suave no escuro (par de --warning-bg) */
  /* No escuro o chip invertido fica claro (#fafafa); o amarelo da marca não
     passa AA como texto sobre claro. Gold escurecido: contraste ≈ 5:1 sobre
     #fafafa, mantendo a leitura "dourado/alerta". */
  --timer-idle: #846a00;

  /* Sombras intensificadas */
  --sh-sm: 0 1px 3px rgba(0,0,0,.4), 0 1px 2px rgba(0,0,0,.2);
  --sh-md: 0 4px 12px rgba(0,0,0,.4), 0 2px 4px rgba(0,0,0,.2);
  --sh-lg: 0 12px 32px rgba(0,0,0,.5), 0 4px 8px rgba(0,0,0,.3);

  /* Code theme — tema escuro (calibrado, contraste AA sobre #1b1b1b). */
  --code-bg: #1b1b1b;
  --code-fg: #e6e6e6;
  --code-border: #2e2e2e;
  --code-keyword: #c792ea;
  --code-string: #7fd6a0;
  --code-number: #f2b35e;
  --code-comment: #8a8a8a;
  --code-property: #82c5f5;
  --code-punct: #b8b8b8;

  color-scheme: dark;
}

/* ═══════════════════════════════════════════════════════════════════════════
   PREMIUM · MARKETING 360° — Ponte Tailwind CSS v4
   Só faz sentido em projetos com Tailwind v4 (config CSS-first). Gera as
   utilities semânticas: bg-bg, bg-surface, bg-sunken, text-ink, text-muted,
   text-subtle, border-border, border-border-strong, bg-brand, text-on-brand,
   bg-success-bg, text-danger, …
   Projetos sem Tailwind: importe apenas tokens.css/base.css e ignore este.
   ═══════════════════════════════════════════════════════════════════════════ */

/* Variante dark dirigida por classe (html.dark), padrão dos sistemas Premium.
   O toggle de tema estampa/remove .dark no <html> (chave localStorage
   `premium-theme`; sem escolha salva, siga prefers-color-scheme). */
@custom-variant dark (&:where(.dark, .dark *));

@theme inline {
  --font-sans: var(--font-ubuntu, "Ubuntu"), system-ui, sans-serif;

  /* Semânticos → --c-* (utilities bg-surface, text-ink, border-border, …) */
  --color-bg: var(--c-bg);
  --color-surface: var(--c-surface);
  --color-sunken: var(--c-sunken);
  --color-ink: var(--c-ink);
  --color-muted: var(--c-muted);
  --color-subtle: var(--c-subtle);
  --color-border: var(--c-border);
  --color-border-strong: var(--c-border-strong);

  /* Compatibilidade: utilities bg-background / text-foreground existentes */
  --color-background: var(--c-bg);
  --color-foreground: var(--c-ink);

  /* Marca (fixa — não muda por tema) */
  --color-brand: var(--brand-yellow);
  --color-on-brand: #000000;

  /* Status */
  --color-success: var(--success);
  --color-success-bg: var(--success-bg);
  --color-warning: var(--warning);
  --color-warning-bg: var(--warning-bg);
  --color-danger: var(--danger);
  --color-danger-bg: var(--danger-bg);
  --color-info: var(--info);
  --color-info-bg: var(--info-bg);

  /* Alerta fixo (fixo nos dois temas) */
  --color-alert-solid: var(--alert-solid);
  --color-alert-solid-hover: var(--alert-solid-hover);
  --color-on-alert-solid: var(--on-alert-solid);
}

/* ═══════════════════════════════════════════════════════════════════════════
   PREMIUM · MARKETING 360° — Base global de identidade
   Tipografia, seleção e scrollbar padrão dos sistemas Premium.
   A fonte Ubuntu (300/400/500/700) NÃO é embutida no pacote: cada app a
   carrega do seu jeito (next/font, @font-face ou <link>), com fallback
   system-ui garantido aqui. A família vem de var(--font-ubuntu), que o
   next/font declara (o nome que ele gera não casa com "Ubuntu"); sem a
   variável, vale o nome literal, como no @font-face ou no <link>.
   ═══════════════════════════════════════════════════════════════════════════ */

body {
  font-family: var(--font-ubuntu, "Ubuntu"), system-ui, sans-serif;
  background: var(--c-bg);
  color: var(--c-ink);
  -webkit-font-smoothing: antialiased;
}

/* Seleção de texto: amarelo da marca com texto preto, nos dois temas. */
::selection {
  background: var(--yellow);
  color: #000;
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-thumb {
  background: var(--premium-mist);
  border-radius: 999px;
  border: 2px solid var(--premium-paper);
}

/* Rótulo "eyebrow" (10px/700, uppercase, tracking largo) — assinatura
   tipográfica da marca acima de títulos e em cabeçalhos de coluna. */
.eyebrow {
  font-weight: 700;
  font-size: 10px;
  letter-spacing: 0.20em;
  text-transform: uppercase;
  color: var(--premium-gray);
}

/* Campo de busca: um controle de limpar por campo, sempre o do sistema.
   Chrome e Safari desenham um "x" nativo em todo input[type="search"], que
   duplicava o X do sistema (e o Firefox não desenha nenhum). O campo continua
   type="search": teclado "Buscar" no celular, Esc limpa, papel searchbox. */
input[type="search"]::-webkit-search-cancel-button,
input[type="search"]::-webkit-search-decoration,
input[type="search"]::-webkit-search-results-button,
input[type="search"]::-webkit-search-results-decoration {
  -webkit-appearance: none;
  appearance: none;
  display: none;
}

/* ═══════════════════════════════════════════════════════════════════════════
   PREMIUM · MARKETING 360° — Padrões de movimento compartilhados
   Curva única --ease (definida em tokens.css) e keyframes de identidade.
   Tudo condicionado a prefers-reduced-motion: sem preferência de movimento,
   nada anima (o significado permanece pela cor/estado estático).
   Presets de overlay (modal, slide-over, menu, toast) são código de app —
   ver docs/motion.md.
   ═══════════════════════════════════════════════════════════════════════════ */

/* Fade-in de tela para skeletons/rotas (150ms, sem deslocamento). */
@media (prefers-reduced-motion: no-preference) {
  @keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
  }
}

/* Crossfade de conteúdo em navegação server-nav (View Transitions API,
   progressive enhancement). Duração curta para não pesar. */
@media (prefers-reduced-motion: no-preference) {
  ::view-transition-old(root),
  ::view-transition-new(root) {
    animation-duration: 0.2s;
  }
}

/* Flash sutil de fundo em item recém-chegado (tempo real / envio otimista).
   Token temático com par escuro próprio (--gold-bg), dissolvendo em ~600ms. */
@media (prefers-reduced-motion: no-preference) {
  @keyframes flashNovo {
    from { background-color: var(--gold-bg); }
    to { background-color: transparent; }
  }
  .flash-novo {
    animation: flashNovo 0.6s var(--ease);
    border-radius: var(--r-md);
  }
}

/* Pulso suave de alerta discreto (ex.: cronômetro parado). Opacidade 1→0.55,
   ciclo lento (1.6s) e simétrico (ease-in-out) — exceção documentada à curva
   única. Sob prefers-reduced-motion NÃO anima — o alerta permanece pela cor. */
@media (prefers-reduced-motion: no-preference) {
  @keyframes timerPulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.55; }
  }
  .timer-pulse {
    animation: timerPulse 1.6s ease-in-out infinite;
  }
}

/* Botão de lido virando verde (padrão "Botão de lido", v0.10.0): encolhe, passa
   do tamanho e volta (--ease-mola); uma onda verde se abre ao redor; os traços
   do ícone se desenham. Aplicar .lido-vira no indicador verde no instante da
   troca. Sob prefers-reduced-motion a troca é direta. */
@media (prefers-reduced-motion: no-preference) {
  @keyframes lidoPop {
    0% { transform: scale(1); }
    35% { transform: scale(0.8); }
    70% { transform: scale(1.14); }
    100% { transform: scale(1); }
  }
  @keyframes lidoOnda {
    from { box-shadow: 0 0 0 0 color-mix(in srgb, var(--success) 45%, transparent); }
    to { box-shadow: 0 0 0 12px transparent; }
  }
  @keyframes lidoTraco {
    from { stroke-dashoffset: 28; }
    to { stroke-dashoffset: 0; }
  }
  .lido-vira {
    animation: lidoPop 0.4s var(--ease-mola), lidoOnda 0.7s var(--ease);
  }
  .lido-vira svg {
    stroke-dasharray: 28;
    animation: lidoTraco 0.38s var(--ease) 0.06s both;
  }

  /* Item que chegou em tempo real com o painel de cards aberto: borda amarela por
     um instante (par do .flash-novo). A entrada pela direita é do Motion. */
  @keyframes flashBorda {
    0%, 45% {
      border-color: var(--brand-yellow);
      box-shadow: 0 0 0 3px color-mix(in srgb, var(--brand-yellow) 50%, transparent), var(--sh-md);
    }
  }
  .flash-borda {
    animation: flashBorda 1.8s var(--ease) both;
  }
}

/* ═══════════════════════════════════════════════════════════════════════════
   PADRÃO · Barra de progresso indeterminada do auto-save (opt-in)
   Acompanha o padrão de edição com auto-save (docs/formularios.md): barra fina
   que desliza durante a gravação. Sob prefers-reduced-motion vira barra cheia
   estática — o estado "salvando" permanece comunicado sem movimento.
   Aplicar a classe .autosave-bar no preenchimento da barra.
   ═══════════════════════════════════════════════════════════════════════════ */

.autosave-bar {
  width: 40%;
  transform: translateX(-100%);
}
@media (prefers-reduced-motion: no-preference) {
  @keyframes autosaveBar {
    from {
      transform: translateX(-100%);
    }
    to {
      transform: translateX(300%);
    }
  }
  .autosave-bar {
    animation: autosaveBar 1.1s var(--ease) infinite;
  }
}
@media (prefers-reduced-motion: reduce) {
  .autosave-bar {
    width: 100%;
    transform: none;
  }
}

/* ═══════════════════════════════════════════════════════════════════════════
   PADRÃO · Bloco de código com realce (opt-in)
   Completa os tokens --code-* de tokens.css com as classes emitidas pelo
   realçador leve (sem hex no componente) e a rolagem horizontal fina.
   Ver docs/ui-guidelines.md §4.25 e a implementação de referência em
   https://github.com/agenciapremium/tasks/blob/main/src/components/ui/code-block.tsx
   ═══════════════════════════════════════════════════════════════════════════ */

.code-scroll {
  scrollbar-width: thin;
  scrollbar-color: var(--code-punct) transparent;
}
.code-scroll::-webkit-scrollbar {
  height: 8px;
}
.code-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.code-scroll::-webkit-scrollbar-thumb {
  background: var(--code-border);
  border-radius: var(--r-pill);
}
/* Tokens de realce — classes emitidas pelo realçador. */
.tok-keyword { color: var(--code-keyword); }
.tok-string { color: var(--code-string); }
.tok-number { color: var(--code-number); }
.tok-comment { color: var(--code-comment); font-style: italic; }
.tok-property { color: var(--code-property); }
.tok-punct { color: var(--code-punct); }

/* ═══════════════════════════════════════════════════════════════════════════
   PADRÃO · Barra de rolagem da coluna do Kanban (opt-in)
   Fina, trilho transparente, thumb em token neutro sobre o fundo --premium-bone
   da coluna. Webkit + Firefox; cores só por token (adaptam ao dark mode via
   fachada semântica --premium-*). Ver docs/ui-guidelines.md §4.6/§9.
   Aplicar a classe .kanban-col-scroll no corpo rolável de cada coluna.
   ═══════════════════════════════════════════════════════════════════════════ */

.kanban-col-scroll {
  scrollbar-width: thin;
  scrollbar-color: var(--premium-silver) transparent;
}
.kanban-col-scroll::-webkit-scrollbar {
  width: 8px;
}
.kanban-col-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.kanban-col-scroll::-webkit-scrollbar-thumb {
  background: var(--premium-silver);
  border-radius: var(--r-pill);
  border: 2px solid transparent;
  background-clip: padding-box;
}
.kanban-col-scroll:hover::-webkit-scrollbar-thumb {
  background: var(--premium-steel);
}

/* ═══════════════════════════════════════════════════════════════════════════
   PADRÃO · Pilha com rolagem sem barra (opt-in, v0.10.0)
   Lista de cards soltos que rola sem barra aparente; o degradê por máscara na
   borda que ainda tem conteúdo avisa que tem mais. Nasceu no "Alerta fixo"
   (v0.8.0) e é compartilhado com o "Painel de cards flutuantes".
   Aplicar .pilha-rolagem no contêiner rolável e escrever `data-mais` =
   "acima" | "abaixo" | "ambos" (ou nenhum) medindo scrollTop/clientHeight/
   scrollHeight na rolagem e quando a lista muda de tamanho. A máscara é canal
   alfa, não cor: o preto só marca o que fica opaco (vale nos dois temas).
   Dica: padding + margem negativa de mesma medida em volta da lista evita que
   a sombra dos cards seja cortada pela rolagem.
   ═══════════════════════════════════════════════════════════════════════════ */

.pilha-rolagem {
  overflow-y: auto;
  scrollbar-width: none;
  overscroll-behavior: contain;
}
.pilha-rolagem::-webkit-scrollbar {
  display: none;
}
.pilha-rolagem[data-mais="abaixo"] {
  -webkit-mask-image: linear-gradient(to bottom, #000 calc(100% - 44px), transparent);
  mask-image: linear-gradient(to bottom, #000 calc(100% - 44px), transparent);
}
.pilha-rolagem[data-mais="acima"] {
  -webkit-mask-image: linear-gradient(to top, #000 calc(100% - 44px), transparent);
  mask-image: linear-gradient(to top, #000 calc(100% - 44px), transparent);
}
.pilha-rolagem[data-mais="ambos"] {
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 44px, #000 calc(100% - 44px), transparent);
  mask-image: linear-gradient(to bottom, transparent, #000 44px, #000 calc(100% - 44px), transparent);
}

/* ═══════════════════════════════════════════════════════════════════════════
   PADRÃO · Pílula de ação e de seleção (opt-in, v0.10.0)
   A pílula tem o desenho do chip de filtro (docs/ui-guidelines.md §3.4); aqui
   ficam só as transições que o chip não precisa:
   - .pilula-flutuante: pílula sobre scrim (alvo de 40px e --sh-md no
     componente); as cores seguem o chip (150ms) e a volta de uma pílula oculta
     também é suave.
   - .pilula-oculta: pílula de ação que deixou de se aplicar. Some com fade e só
     depois sai da árvore (visibility atrasado), sem deslocar os vizinhos; tire
     também do Tab (tabindex="-1") no componente.
   ═══════════════════════════════════════════════════════════════════════════ */

.pilula-flutuante {
  transition:
    border-color 0.15s var(--ease),
    color 0.15s var(--ease),
    background-color 0.15s var(--ease),
    box-shadow 0.15s var(--ease),
    opacity 0.18s var(--ease),
    transform 0.18s var(--ease),
    visibility 0s;
}
.pilula-oculta {
  opacity: 0;
  transform: scale(0.9);
  visibility: hidden;
  pointer-events: none;
  transition:
    opacity 0.18s var(--ease),
    transform 0.18s var(--ease),
    visibility 0s linear 0.18s;
}

/* ═══════════════════════════════════════════════════════════════════════════
   PADRÃO · Atraso da dica contextual (opt-in, v0.11.0)
   A dica (Tooltip) aparece 300 ms depois que o ponteiro para sobre o gatilho:
   passar rápido por uma barra de ícones não faz nada cintilar. No foco por
   teclado ela aparece na hora. O atraso mora numa custom property registrada
   (--tt-delay), e não numa classe do componente, porque precisa ser herdado e
   transicionável: um contêiner com `data-tooltip-group` (uma barra de ícones,
   por exemplo) zera o atraso depois que o ponteiro já passou 300 ms dentro
   dele, e mudar de um ícone para o vizinho mostra a dica na hora, como num
   menu; sair do grupo devolve o atraso na mesma hora.
   Contrato com o app:
   - o balão usa `transition-delay: var(--tt-delay, 300ms)` no hover do
     gatilho e `0ms` no foco (`:focus-within` do wrapper);
   - o wrapper zera a variável sob `:focus-within`, para quem chega pelo
     teclado nunca esperar, mesmo com o ponteiro parado em cima;
   - uma instância com atraso próprio escreve `--tt-delay` no wrapper e deixa
     de obedecer ao grupo.
   Não é token de marca: é tempo de interação de um componente. Anatomia,
   acessibilidade e props em docs/componentes.md §Tooltip e
   docs/ui-guidelines.md §4.34.
   ═══════════════════════════════════════════════════════════════════════════ */

@property --tt-delay {
  syntax: "<time>";
  inherits: true;
  initial-value: 300ms;
}

[data-tooltip-group] {
  /* Volta ao atraso cheio assim que o ponteiro sai do grupo. */
  transition: --tt-delay 0s;
}

[data-tooltip-group]:hover {
  --tt-delay: 0ms;
  transition: --tt-delay 0s 300ms;
}
